def parse_record(row):
    """Turn a database row into a display record."""
    result = {
        "id": str(row["id"]),
        "label": normalize_label(row["label"]),
        "tags": split_tags(row.get("tags", "")),
        "click_rate": None,
    }
    if row.get("views"):
        result["click_rate"] = round(row.get("clicks", 0) / row["views"], 4)
    return result

